// === Tab: mySketch ===
// Binary Flag — a wavy flag woven from alternating 1s and 0s
// For #WCCChallenge "Binary" 30th August 2026 to 6th September 2026

let cols = 30;
let rows = 24;
let flagW = 50;
let flagH = 200;
let poleX = 130;
let topY = 300;
let t = 0;

let fireworks = [];

// Graphics buffers
let fireworkLayer;
let flagLayer;


function setup() {
  createCanvas(800, 600);

  // Fireworks have trails
  fireworkLayer = createGraphics(width, height);

  // Flag is redrawn cleanly every frame
  flagLayer = createGraphics(width, height);

  // Set up text on both buffers
  textFont('Courier New');
  textAlign(CENTER, CENTER);
  textStyle(BOLD);

  fireworkLayer.textFont('Courier New');
  fireworkLayer.textAlign(CENTER, CENTER);
  fireworkLayer.textStyle(BOLD);

  flagLayer.textFont('Courier New');
  flagLayer.textAlign(CENTER, CENTER);
  flagLayer.textStyle(BOLD);
}


function draw() {





  // Completely clean background.

  background(8, 12, 18);



  // FIREWORK LAYER



  fireworkLayer.background(8, 12, 18, 35);

  fireworkLayer.push();
  fireworkLayer.noStroke();

  if (random() < 0.04 && topY <= 110) {
    fireworks.push(new Firework());
  }

  for (let i = fireworks.length - 1; i >= 0; i--) {

    fireworks[i].update();


    fireworks[i].show(fireworkLayer);

    if (fireworks[i].done()) {
      fireworks.splice(i, 1);
    }
  }

  fireworkLayer.pop();


  // Put the fireworks onto the main canvas
  image(fireworkLayer, 0, 0);



  // FLAG LAYER


  // Completely clear the flag buffer.
  // Nothing from the previous frame survives.

push();
flagLayer.clear();

  drawFlag(flagLayer);

  // Composite the clean flag over the fireworks
  image(flagLayer, 0, 0);
pop();


  // POLE


  drawPole();



  // GLOW / VIGNETTE


  drawGlowEdge();



  // ANIMATION
  // Flag rises and unfurls

  if (topY > 110) {
    topY -= 2;
    flagW += 1;
  }



  t += 0.02;
}


// ==================================================
// FLAG


function drawFlag(g) {

g.push();
  const cellW = flagW / (cols - 1);
  const cellH = flagH / (rows - 1);

  for (let c = 0; c < cols; c++) {

    const u = c / (cols - 1);

    // Two overlapping waves
    const phase =
      u * PI * 1.9 - t * 2.2;

    const phase2 =
      u * TWO_PI * 1.1 - t * 1.4;

    // Amplitude increases towards free edge
    const amp =
      34 * pow(u, 1.3);

    const wave =
      sin(phase) * amp +
      sin(phase2) * amp * 0.35;

    // Horizontal foreshortening
    const x =
      poleX +
      u * flagW -
      cos(phase) * amp * 0.35;

    // Vertical movement / droop
    const yShift =
      wave * 0.45 +
      u * u * 18;

    // Fake depth
    const depth = sin(phase);

    const sc =
      map(depth, -1, 1, 0.80, 1.18);

    const shade =
      map(depth, -1, 1, 0.32, 1.0);


    for (let r = 0; r < rows; r++) {

      const v = r / (rows - 1);

      // Vertical ripple
      const vy =
        sin(phase * 0.6 + v * 2.4) *
        amp * 0.18;

      const y =
        topY +
        v * cellH * (rows - 1) * sc -
        (flagH * (sc - 1)) * 0.5 +
        yShift +
        vy;


      // Alternating binary
      const bit =
        (c + r) % 2 === 0 ? '1' : '0';


      // Colours
      if (bit === '1') {

        g.fill(
          70 * shade,
          255 * shade,
          170 * shade,
          255
        );

      } else {

        g.fill(
          30 * shade,
          130 * shade,
          120 * shade,
          200
        );
      }


      g.textSize(
        cellH * 0.95 * sc
      );

      g.text(bit, x, y);
    }
  }
g.pop();


  // TEXT ON FLAG LAYER
  // --------------------------------------------------

  if (topY <= 110) {

    g.push();

    g.textWeight(400);
    g.textStyle(NORMAL);
    g.textAlign(RIGHT);

    g.fill(70, 255, 170);

    g.textSize(25);

    g.text(
      "There are 10 types of people in the world",
      800,
      420
    );

    g.text(
      "Those that understand binary",
      620,
      450
    );

    g.text(
      "And those that don't",
      520,
      480
    );

    g.pop();


    // Cursive M is also part of the clean flag layer

	drawCursiveM_p5js2(
      g,
      750,
      580,
      30
    );
  }

}



// FLAG POLE


function drawPole() {

  noStroke();

  // Pole
  fill(150, 160, 175);
  rect(
    poleX - 6,
    90,
    8,
    430,
    4
  );

  fill(90, 100, 115);

  rect(
    poleX - 2,
    90,
    4,
    430,
    2
  );


  // Finial
  fill(192, 192, 192);

  circle(
    poleX - 2,
    84,
    16
  );
}



// GLOW / VIGNETTE


function drawGlowEdge() {

  noFill();

  for (let i = 0; i < 60; i++) {

    stroke(
      8,
      12,
      18,
      6
    );

    rect(
      i,
      i,
      width - i * 2,
      height - i * 2
    );
  }

  noStroke();
}



// RANDOM FIREWORK COLOUR

function randomColor() {

  let channels = [
    random(200, 255),
    random(80, 200),
    random(20, 100)
  ];

  for (let i = channels.length - 1; i > 0; i--) {

    let j = floor(random(i + 1));

    [
      channels[i],
      channels[j]
    ] = [
      channels[j],
      channels[i]
    ];
  }

  return {
    r: channels[0],
    g: channels[1],
    b: channels[2]
  };
}



// FIREWORK


class Firework {

  constructor(x) {

    this.col = randomColor();

    this.rocket = new Particle(
      x || random(
        width * 0.15,
        width * 0.85
      ),
      height,
      true,
      this.col
    );

    this.exploded = false;
    this.particles = [];
  }


  done() {

    return (
      this.exploded &&
      this.particles.length === 0
    );
  }


  update() {

    if (!this.exploded) {

      this.rocket.applyForce(
        createVector(0, 0.05)
      );

      this.rocket.update();

      if (this.rocket.vel.y >= 0) {

        this.exploded = true;

        this.explode();
      }
    }


    for (
      let i = this.particles.length - 1;
      i >= 0;
      i--
    ) {

      let p = this.particles[i];

      p.applyForce(
        createVector(0, 0.04)
      );

      p.update();

      if (p.isDead()) {

        this.particles.splice(i, 1);
      }
    }
  }


  explode() {

    let count =
      floor(random(60, 120));


    for (let i = 0; i < count; i++) {

      let varCol = {

        r: constrain(
          this.col.r + random(-30, 30),
          0,
          255
        ),

        g: constrain(
          this.col.g + random(-30, 30),
          0,
          255
        ),

        b: constrain(
          this.col.b + random(-30, 30),
          0,
          255
        )
      };


      this.particles.push(
        new Particle(
          this.rocket.pos.x,
          this.rocket.pos.y,
          false,
          varCol
        )
      );
    }
  }


  // Pass the graphics buffer into show()
  show(g) {

    if (!this.exploded) {
      this.rocket.show(g);
    }

    for (let p of this.particles) {
      p.show(g);
    }
  }
}



// PARTICLE


class Particle {

  constructor(x, y, isRocket, col) {

    this.pos =
      createVector(x, y);

    this.isRocket =
      isRocket;

    this.col =
      col;

    this.digit =
      random() < 0.5 ? '1' : '0';

    this.lifespan = 100;

    this.acc =
      createVector(0, 0);


    if (isRocket) {

      this.vel =
        createVector(
          random(-0.8, 0.8),
          random(-14, -9)
        );

      this.size = 16;

    } else {

      let angle =
        random(TWO_PI);

      let speed =
        random(1, 8);

      this.vel =
        createVector(
          cos(angle) * speed,
          sin(angle) * speed
        );

      this.size =
        random(10, 18);
    }
  }


  applyForce(f) {
    this.acc.add(f);
  }


  update() {

    if (!this.isRocket) {

      this.vel.mult(0.96);

      this.lifespan -= 1.5;

      if (random() < 0.03) {

        this.digit =
          this.digit === '1'
            ? '0'
            : '1';
      }
    }


    this.vel.add(this.acc);

    this.pos.add(this.vel);

    this.acc.mult(0);
  }


  isDead() {

    return this.lifespan <= 0;
  }


  // Draw onto whichever graphics buffer is supplied
  show(g) {

    g.noStroke();


    if (this.isRocket) {

      g.textSize(this.size);

      g.fill(
        this.col.r,
        this.col.g,
        this.col.b,
        230
      );

      g.text(
        this.digit,
        this.pos.x,
        this.pos.y
      );

    } else {

      let alphas =
        map(
          this.lifespan,
          0,
          100,
          0,
          255
        );

      let dimFactor =
        map(
          this.lifespan,
          0,
          100,
          0.3,
          1.0
        );


      let r =
        this.col.r * dimFactor;

      let gCol =
        this.col.g * dimFactor;

      let b =
        this.col.b * dimFactor;


      // Outer glow
      g.textSize(
        this.size + 4
      );

      g.fill(
        r,
        gCol,
        b,
        alphas * 0.3
      );

      g.text(
        this.digit,
        this.pos.x,
        this.pos.y
      );


      // Core digit
      g.textSize(
        this.size
      );

      g.fill(
        r,
        gCol,
        b,
        alphas
      );

      g.text(
        this.digit,
        this.pos.x,
        this.pos.y
      );
    }
  }
}



// CURSIVE M


function drawCursiveM_p5js2(g, x, y, size) {

	g.push();
  g.noFill();

  g.stroke('yellow');

  g.strokeWeight(
    size * 0.06
  );

  let h =
    size * 0.7;


  // Initial upstroke and first hump
  g.beginShape();

  g.splineVertex(
    x,
    y - 20
  );

  g.splineVertex(
    x + size * 0.05,
    y - h
  );

  g.splineVertex(
    x + size * 0.15,
    y - h
  );

  g.splineVertex(
    x + size * 0.25,
    y - h
  );

  g.splineVertex(
    x + size * 0.3,
    y
  );

  g.endShape();


  // Second hump
  g.beginShape();

  g.splineVertex(
    x + size * 0.3,
    y
  );

  g.splineVertex(
    x + size * 0.425,
    y - h
  );

  g.splineVertex(
    x + size * 0.575,
    y - h
  );

  g.splineVertex(
    x + size * 0.6,
    y
  );

  g.endShape();


  // Third hump
  g.beginShape();

  g.splineVertex(
    x + size * 0.6,
    y
  );

  g.splineVertex(
    x + size * 0.725,
    y - h
  );

  g.splineVertex(
    x + size * 0.875,
    y - h
  );

  g.splineVertex(
    x + size * 0.9,
    y
  );

  g.endShape();


  // Trailing exit stroke
  g.beginShape();

  g.splineVertex(
    x + size * 0.9,
    y
  );

  g.splineVertex(
    x + size * 0.95,
    y + size * 0.15
  );

  g.splineVertex(
    x + size * 1.1,
    y + size * 0.1
  );

  g.splineVertex(
    x + size * 1.15,
    y
  );

  g.endShape();
	g.pop();
}

